package com.ruoyi.majorpilot.report.claims;
import com.fasterxml.jackson.databind.*;
import com.ruoyi.majorpilot.report.core.*;
import static com.ruoyi.majorpilot.report.core.ReportModels.*;
import java.math.*;
import java.util.*;

/** Reviewed templates only. Student analysis and arbitrary summaries never become report prose. */
public final class ClaimCatalogBuilder {
    private final ObjectMapper mapper;
    public ClaimCatalogBuilder(ObjectMapper mapper){this.mapper=mapper;}
    public List<Entry> build(ReportInput input){var entries=new ArrayList<Entry>();boolean comparison=input.header().reportType()==ReportType.COMPARISON;
        if(comparison){rule(entries,"SCOPE_AND_SOURCES","scope","本报告并列记录各次体验的证据，不进行专业总分或优劣排名。",null,null,"scope");for(var source:input.sources())comparison(entries,source);rule(entries,"UNKNOWNS","unknown","本次任务无法判断长期能力、录取结果或职业表现；未知维度不补分数。",null,null,"unknown");rule(entries,"NEXT_VERIFICATION","verify","可以通过更多真实课程、项目或访谈继续验证兴趣；单次任务不足以作最终专业决定。",null,null,"verify");next(entries,"REMAINING_MAJOR",input.nextRecommendation());}
        else{var source=input.sources().getFirst();String major=source.majorCode();rule(entries,"OVERVIEW","scope","这是一份关于本次“"+source.pins().taskTitle()+"”体验的记录，分别呈现偏好、操作与任务结果，不是专业适合度评定。",major,null,"scope");
            var actions=source.items().stream().filter(i->i.type().equals("STEP_RESPONSE")&&i.allowedClaimTypes().contains("OBSERVED_FACT")).toList();if(actions.size()<3)throw new ReportInputException("REPORT_SOURCE_INVALID");for(var item:actions.stream().limit(5).toList())fact(entries,source,"WHAT_YOU_DID",item,actionText(source,item),"action:"+item.key());
            self(entries,source,"EXPERIENCE_PREFERENCE","interestingStepKeys","interest",null);self(entries,source,"EXPERIENCE_PREFERENCE","continueSimilarWork","continuation",null);
            fact(entries,source,"CURRENT_PREPARATION",actions.getFirst(),"你在本次任务中完成了一个受引导的操作或选择；这只说明本次提交行为，不证明已独立掌握相关知识。","preparation-action");self(entries,source,"CURRENT_PREPARATION","difficultySources","difficulty",null);
            var executions=executions(source);if(executions.isEmpty())throw new ReportInputException("REPORT_SOURCE_INVALID");for(var item:executions)fact(entries,source,"TASK_PERFORMANCE",item,executionText(source.majorCode(),item.value()),"execution:"+item.key());
            rule(entries,"WORK_STYLE_CONNECTION","focus",focus(major),major,null,"focus");bounded(entries,source,"WORK_STYLE_CONNECTION");
            rule(entries,"EVIDENCE_BOUNDARIES","synthetic","本次使用固定合成数据。服务端复核只验证固定输入与算法下的结果，不验证学生分析、因果判断或预期收益。",major,null,"synthetic");
            var hint=source.items().stream().filter(i->i.type().equals("ASSISTANCE_CONTEXT")).findFirst();if(hint.isPresent())fact(entries,source,"EVIDENCE_BOUNDARIES",hint.get(),"本次体验中请求过提示支持；提示层级、次数和耗时不能用来推断能力高低。","support");
            rule(entries,"OTHER_MAJOR_DIFFERENCES","differences","AI侧重模型行为与迭代，DS侧重数据质量、关系与不确定性，BA侧重指标口径和行动验证；这些是工作方式差异，不是难度或适合度排名。",null,null,"differences");next(entries,"NEXT_EXPERIENCE",input.nextRecommendation());}
        entries.sort(Comparator.comparing(Entry::statementKey));return List.copyOf(entries);
    }
    private void comparison(List<Entry> entries,Source s){String m=s.majorCode();var actions=s.items().stream().filter(i->i.type().equals("STEP_RESPONSE")&&i.allowedClaimTypes().contains("OBSERVED_FACT")).toList();if(actions.isEmpty())throw new ReportInputException("REPORT_SOURCE_INVALID");fact(entries,s,"WORK_COMPLETED",actions.getFirst(),actionText(s,actions.getFirst()),"completed");self(entries,s,"SELF_REPORTED_EXPERIENCE","interestingStepKeys","interest",null);self(entries,s,"SELF_REPORTED_EXPERIENCE","difficultySources","difficulty",null);
        var executions=executions(s);if(executions.isEmpty())throw new ReportInputException("REPORT_SOURCE_INVALID");fact(entries,s,"MAJOR_SPECIFIC_EXPERIENCE",executions.getFirst(),executionText(m,executions.getFirst().value()),"specific");bounded(entries,s,"MAJOR_SPECIFIC_EXPERIENCE");
        for(String dim:DIMENSIONS){switch(dim){case "PROBLEM_INTEREST"->self(entries,s,"COMMON_DIMENSIONS","interestingStepKeys","dimension:"+dim,dim);case "CONTINUATION_WILLINGNESS"->self(entries,s,"COMMON_DIMENSIONS","continueSimilarWork","dimension:"+dim,dim);case "WORK_FOCUS"->rule(entries,"COMMON_DIMENSIONS","focus",focus(m),m,dim,"dimension:"+dim);case "HELP_AND_ITERATION"->{var hint=s.items().stream().filter(i->i.type().equals("ASSISTANCE_CONTEXT")&&i.allowedClaimTypes().contains("OBSERVED_FACT")).findFirst();if(hint.isPresent())add(entries,"COMMON_DIMENSIONS",ClaimType.OBSERVED_FACT,"本次请求过提示支持；不能据此判断独立能力或与其他专业相比的高低。",List.of(hint.get().publicId()),m,dim,"dimension:"+dim,mapper.createObjectNode());else unknown(entries,"COMMON_DIMENSIONS",m,dim,"dimension:"+dim);}default->unknown(entries,"COMMON_DIMENSIONS",m,dim,"dimension:"+dim);}}
    }
    private List<EvidenceValue> executions(Source s){return s.items().stream().filter(i->i.type().equals("VERIFIED_EXECUTION")&&i.allowedClaimTypes().contains("OBSERVED_FACT")).toList();}
    private String actionText(Source source,EvidenceValue item){String step=item.key().startsWith("step:")?item.key().substring(5):"";String label=source.pins().stepTitles().get(step);if(label==null)throw new ReportInputException("REPORT_SOURCE_INVALID");return "你在“"+label+"”环节提交了选择、配置或分析；记录提交行为不等于确认分析正确。";}
    private void fact(List<Entry> entries,Source s,String section,EvidenceValue item,String text,String slot){if(!item.allowedClaimTypes().contains("OBSERVED_FACT"))throw new ReportInputException("REPORT_SOURCE_INVALID");add(entries,section,ClaimType.OBSERVED_FACT,text,List.of(item.publicId()),s.majorCode(),null,slot,item.value());}
    private void self(List<Entry> entries,Source source,String section,String field,String slot,String dimension){var item=source.items().stream().filter(i->i.key().equals("reflection:"+field)&&i.type().equals("SELF_REPORT")&&i.allowedClaimTypes().contains("STUDENT_SELF_REPORT")).findFirst();if(item.isEmpty()){unknown(entries,section,source.majorCode(),dimension,slot);return;}var i=item.get();String text;
        if(field.equals("interestingStepKeys")){var values=enumeration(i.value(),source.pins().stepTitles().keySet(),true);text=values.equals(List.of("NONE"))?"你表示本次没有明确感兴趣的环节；这不是对专业长期兴趣的结论。":"你表示本次感兴趣的环节包括：“"+String.join("、",values.stream().map(source.pins().stepTitles()::get).toList())+"”。这里保留本次自述，不对多个环节排序。";}
        else if(field.equals("difficultySources")){var names=Map.of("KNOWLEDGE","知识背景","TOOLS","工具操作","TIME","时间安排","WORK_STYLE","工作方式","OTHER","其他方面","NONE","没有明确困难");var values=enumeration(i.value(),names.keySet(),true);text="你表示本次困难来源为："+String.join("、",values.stream().map(names::get).toList())+"。这不是客观能力评分。";}
        else{if(!i.value().isTextual())throw new ReportInputException("REPORT_SOURCE_INVALID");text=switch(i.value().asText()){case "YES"->"你表示愿意继续尝试类似工作；这是本次继续意愿，不是最终专业选择。";case "UNSURE"->"你表示尚不确定是否愿意继续类似工作。";case "NO"->"你表示本次不愿继续类似工作；不将它扩大为长期能力或专业判断。";default->throw new ReportInputException("REPORT_SOURCE_INVALID");};}
        add(entries,section,ClaimType.STUDENT_SELF_REPORT,text,List.of(i.publicId()),source.majorCode(),dimension,slot,mapper.createObjectNode());
    }
    private List<String> enumeration(JsonNode v,Set<String> legal,boolean none){if(!v.isArray()||v.isEmpty()||v.size()>3)throw new ReportInputException("REPORT_SOURCE_INVALID");var list=new ArrayList<String>();for(var x:v){if(!x.isTextual()||!(legal.contains(x.asText())||none&&x.asText().equals("NONE"))||list.contains(x.asText()))throw new ReportInputException("REPORT_SOURCE_INVALID");list.add(x.asText());}if(list.contains("NONE")&&list.size()!=1)throw new ReportInputException("REPORT_SOURCE_INVALID");return list;}
    private void bounded(List<Entry> entries,Source s,String section){for(var item:s.items())if(item.type().equals("DERIVED_INTERPRETATION")){var v=item.value();if(!item.allowedClaimTypes().equals(List.of("BOUNDED_INTERPRETATION"))||!v.path("scope").asText().equals("THIS_EXPERIENCE"))throw new ReportInputException("REPORT_SOURCE_INVALID");String text=switch(v.path("continueSimilarWork").asText()){case "YES"->"你在本次体验中提到了感兴趣的环节，并表示愿意继续类似工作；这是继续探索这类任务的一条线索，不代表已经确定专业方向或具备稳定能力。";case "UNSURE"->"本次有感兴趣的环节，但你仍不确定是否愿意继续类似工作；环节兴趣尚不等于明确的继续意愿。";case "NO"->"本次有感兴趣的环节，但你表示不想继续类似工作；对某个环节有兴趣与愿意继续，并不是同一个选择。";default->throw new ReportInputException("REPORT_SOURCE_INVALID");};add(entries,section,ClaimType.BOUNDED_INTERPRETATION,text,List.of(item.publicId()),s.majorCode(),null,"bounded",v);}}
    private void unknown(List<Entry> e,String section,String major,String dimension,String slot){rule(e,section,"unknown","本次尚无足够证据；不根据任务表现、跳过或提示次数补充推断。",major,dimension,slot);}
    private String focus(String major){return switch(major){case "AI"->"本次AI任务关注模型输出、错误分析与受控迭代；完成任务不等于已经适合AI专业。";case "DATA_SCIENCE"->"本次DS任务关注数据质量、描述统计和不确定性；相关关系不能直接解释为因果。";case "BUSINESS_ANALYTICS"->"本次BA任务关注指标口径、群体比较与行动验证；行动目标不是预测收益。";default->throw new ReportInputException("REPORT_SOURCE_INVALID");};}
    private void next(List<Entry> e,String section,NextProjection n){String text=n.state().equals("ALL_COMPLETED")?"在这份报告固定的生成语境中，三个专业体验均已完成。下一步可用真实课程或项目继续验证，而不是再给出唯一专业排名。":"依照固定的下一专业规则，建议继续体验"+majorName(n.primaryMajor())+"，比较不同工作方式。你仍可选择其他未完成方向；推荐不是能力评定。";add(e,section,ClaimType.NEXT_STEP,text,List.of(),null,null,"next",mapper.valueToTree(n));}
    private String majorName(String m){return switch(m){case "AI"->"人工智能（AI）";case "DATA_SCIENCE"->"数据科学（DS）";case "BUSINESS_ANALYTICS"->"商业分析（BA）";default->throw new ReportInputException("REPORT_SOURCE_INVALID");};}
    private void rule(List<Entry> e,String section,String name,String text,String major,String dimension,String slot){add(e,section,ClaimType.LIMITATION,text,List.of(),major,dimension,slot,mapper.createObjectNode());}
    private void add(List<Entry> entries,String section,ClaimType type,String text,List<String> evidence,String major,String dimension,String slot,JsonNode bindings){String key=(major==null?"GLOBAL":major)+":"+section+":"+slot;Confidence confidence=switch(type){case OBSERVED_FACT->Confidence.DIRECT;case STUDENT_SELF_REPORT->Confidence.SELF_REPORTED;case BOUNDED_INTERPRETATION->Confidence.BOUNDED;default->Confidence.RULE_BASED;};String basis=switch(type){case OBSERVED_FACT->"依据固定任务版本下保存的操作或服务端复核执行记录；不验证学生分析结论。";case STUDENT_SELF_REPORT->"依据本次已提交反思中的明确选项；保留学生自述归属。";case BOUNDED_INTERPRETATION->"依据同一次反思中的兴趣环节和继续意愿，由版本化保守规则生成；只适用于本次体验。";default->"依据已注册的报告边界、任务说明或下一专业规则。";};entries.add(new Entry(key,type,List.of(section),evidence,List.of(type==ClaimType.NEXT_STEP?"next-recommendation-v1":"report-claims-v1"),bindings,type==ClaimType.STUDENT_SELF_REPORT?"STUDENT_SELF_REPORT":"THIS_EXPERIENCE",confidence,Map.of("standard",text),basis,major,dimension,slot));}
    private String executionText(String major,JsonNode value){
        if(major.equals("AI")){if(!value.path("schemaVersion").asText().equals("classifier-result-v1"))throw new ReportInputException("REPORT_SOURCE_INVALID");var c=value.path("candidate");return "固定评估样本共"+count(c,"sampleCount")+"条；本次配置自动处理"+count(c,"autoRoutedCount")+"条，其中正确"+count(c,"correctAutoRoutedCount")+"条，自动处理准确率为"+percent(c.get("autoAccuracy"))+"，覆盖率为"+percent(c.get("coverage"))+"。这些是固定数据与配置的结果，不是学生能力分数。";}
        if(major.equals("DATA_SCIENCE"))return dsExecutionText(value);
        if(!value.path("schemaVersion").asText().equals("ba-result-v1"))throw new ReportInputException("REPORT_SOURCE_INVALID");String windows="基准批次"+count(value.at("/windows/baseline"),"startWeek")+"–"+count(value.at("/windows/baseline"),"endWeek")+"，对比批次"+count(value.at("/windows/comparison"),"startWeek")+"–"+count(value.at("/windows/comparison"),"endWeek")+"，均按每人入组后28天观察。";
        return switch(value.path("operationKey").asText()){
            case "ba-metric"->{String d=value.path("denominator").asText().equals("enrolled_count")?"报名人数":"首次学习人数";var b=value.path("baseline");var c=value.path("comparison");yield windows+"以"+d+"为分母，完成率从"+count(b,"numeratorCount")+"/"+count(b,"denominatorCount")+"（"+percent(b.get("rate"))+"）变为"+count(c,"numeratorCount")+"/"+count(c,"denominatorCount")+"（"+percent(c.get("rate"))+"），变化"+number(value.get("deltaPercentagePoints"))+"个百分点；差异不是原因。";}
            case "ba-funnel"->{var last=value.path("stages").path(5);yield windows+"完成课程阶段累计到达率以报名人数为分母：基准"+percent(last.at("/baseline/cumulativeRate"))+"、对比"+percent(last.at("/comparison/cumulativeRate"))+"。相邻转化率另以上一环节为分母，不混用两者。";}
            case "ba-segments"->{var groups=value.path("segments");if(!groups.isArray()||groups.size()<2||groups.size()>3)throw new ReportInputException("REPORT_SOURCE_INVALID");var parts=new ArrayList<String>();for(var g:groups){String k=g.path("segmentKey").asText();String label=Map.of("FOUNDATIONS","基础课程","APPLIED","应用课程","ORGANIC","自然来源","PARTNER","合作渠道","CAMPAIGN","活动渠道").get(k);if(label==null)throw new ReportInputException("REPORT_SOURCE_INVALID");parts.add(label+"："+count(g.at("/comparison/metric"),"numeratorCount")+"/"+count(g.at("/comparison/metric"),"denominatorCount")+"，支持联系"+number(g.at("/comparison/supportContactsPer100Enrolled"))+"次/100名报名者");}yield windows+"对比期群体结果为"+String.join("；",parts)+"。联系次数不是百分比，不能据此预测行动收益。";}
            default->throw new ReportInputException("REPORT_SOURCE_INVALID");};
    }
    private String count(JsonNode v,String key){var n=v.get(key);if(n==null||!n.isIntegralNumber()||!n.canConvertToLong()||n.asLong()<0)throw new ReportInputException("REPORT_SOURCE_INVALID");return n.asText();}
    private String dsExecutionText(JsonNode v){if(!v.path("schemaVersion").asText().equals("ds-result-v1"))throw new ReportInputException("REPORT_SOURCE_INVALID");String base="固定清洗配置下，输入"+count(v,"inputRows")+"行，保留"+count(v,"retainedRows")+"行；本项分析使用"+count(v,"analysisRows")+"行。";return base+switch(v.path("operationKey").asText()){
        case "ds-quality-clean"->"删除的精确重复为"+count(v.path("quality"),"removedDuplicateRows")+"行，因缺失删除"+count(v.path("quality"),"removedMissingRows")+"行。保留缺失不等于将其补成0，不适用也不是缺失。";
        case "ds-profile"->{var p=v.path("profile");String field=p.path("distributionField").asText();String unit=switch(field){case "avg_session_minutes"->"分钟";case "days_to_first_lesson"->"天";case "assignment_submit_rate"->"比例";default->throw new ReportInputException("REPORT_SOURCE_INVALID");};yield "所选"+fieldLabel(field)+"有"+count(p,"validCount")+"个有效值，中位数为"+(unit.equals("比例")?percent(p.get("median")):number(p.get("median"))+unit)+"。缺失"+count(p,"missingCount")+"条、不适用"+count(p,"notApplicableCount")+"条分别列出，不能用来推断因果。";}
        case "ds-relationship"->relationshipText(v.path("relationship"))+"这些关系不证明因果。";
        case "ds-stratify"->{var groups=v.at("/stratified/strata");if(!groups.isArray()||groups.size()!=2)throw new ReportInputException("REPORT_SOURCE_INVALID");var summaries=new ArrayList<String>();for(var g:groups){var s=g.path("summary");String text=groupLabel(g.path("key").asText())+"层：有效分析"+count(s,"analysisRows")+"行";if(s.path("relationshipMode").asText().equals("SCATTER"))text+="，成对n="+count(s.path("scatter"),"n")+"，r="+number(s.at("/scatter/r"));summaries.add(text);}yield "沿用同一关系进行分层。"+String.join("；",summaries)+"。层内差异仍不证明因果，不能把总体关系自动推广到每一层。";}
        default->throw new ReportInputException("REPORT_SOURCE_INVALID");};}
    private String relationshipText(JsonNode r){if(r.path("relationshipMode").asText().equals("SCATTER"))return "所选"+fieldLabel(r.path("xField").asText())+"与"+fieldLabel(r.path("yField").asText())+"共有"+count(r.path("scatter"),"n")+"对有效值，Pearson r="+number(r.at("/scatter/r"))+"；零方差或不足样本时相关系数不可计算。";if(!r.path("relationshipMode").asText().equals("GROUP_COMPLETION")||!r.path("groups").isArray()||r.path("groups").size()>4)throw new ReportInputException("REPORT_SOURCE_INVALID");var parts=new ArrayList<String>();for(var g:r.path("groups"))parts.add(groupLabel(g.path("key").asText())+" "+count(g,"completedCount")+"/"+count(g,"n")+"（"+percent(g.get("completionRate"))+"）");return "各组完成率使用各自有效样本为分母："+String.join("；",parts)+"。";}
    private String fieldLabel(String field){return switch(field){case "avg_session_minutes"->"平均学习时长";case "days_to_first_lesson"->"首次学习等待天数";case "assignment_submit_rate"->"作业提交比例";default->throw new ReportInputException("REPORT_SOURCE_INVALID");};}
    private String groupLabel(String key){String label=Map.ofEntries(Map.entry("FOUNDATIONS","基础课程"),Map.entry("APPLIED","应用课程"),Map.entry("ORGANIC","自然来源"),Map.entry("PARTNER","合作渠道"),Map.entry("CAMPAIGN","活动渠道"),Map.entry("EARLY","前期"),Map.entry("LATE","后期"),Map.entry("desktop","桌面设备"),Map.entry("mobile","移动设备"),Map.entry("mixed","混合设备"),Map.entry("SAME_DAY","当天"),Map.entry("DAYS_1_2","1–2天"),Map.entry("DAYS_3_6","3–6天"),Map.entry("DAYS_7_PLUS","7天及以上")).get(key);if(label==null)throw new ReportInputException("REPORT_SOURCE_INVALID");return label;}
    private String percent(JsonNode n){if(n==null||n.isMissingNode())throw new ReportInputException("REPORT_SOURCE_INVALID");if(n.isNull())return "不可计算（零分母）";if(!n.isNumber()||n.decimalValue().compareTo(BigDecimal.ZERO)<0||n.decimalValue().compareTo(BigDecimal.ONE)>0)throw new ReportInputException("REPORT_SOURCE_INVALID");return n.decimalValue().multiply(BigDecimal.valueOf(100)).stripTrailingZeros().toPlainString()+"%";}
    private String number(JsonNode n){if(n==null||n.isMissingNode())throw new ReportInputException("REPORT_SOURCE_INVALID");if(n.isNull())return "不可计算";if(!n.isNumber())throw new ReportInputException("REPORT_SOURCE_INVALID");return n.decimalValue().stripTrailingZeros().toPlainString();}
}
